1	// Kiểm tra chế độ đi dạo một mình trên máy tính (docs/superpowers/plans/2026-11-11-di-dao.md, Task 6).
2	//   Trang A `?test&explore=stroll`:
3	//   Mục 1: vào chế độ (cam.mode, lớp body, bảng tham quan ẩn, điểm xuất phát, cao độ lề Cầu Rồng).
4	//   Mục 2: cao độ chân khớp mặt cầu / mặt đất tại 12 điểm mẫu (tia thẳng xuống vào cảnh).
5	//   Mục 3: oracle độc lập với bản đồ: 20 000 bước ngẫu nhiên, mỗi 20 bước 8 tia ngang × 3 cao độ vào tam giác thật của các lưới rắn.
6	//   Mục 4: không ra ngoài mép kè trừ cầu / Cầu Tình Yêu, không thấp hơn mặt đất.
7	//   Mục 5: camera sát tường nhà không chui vào nhà, không xuống dưới mặt đất.
8	//   Mục 8: draw call của người đi dạo đúng 1.
9	//   Mục 7: cầu quay: sơ tán khỏi nhịp, không vào lại khi chưa đóng, đóng thì vào được.
10	//   Mục 6: phím W theo hướng camera, blur dừng (Review Focus 3), gõ trong ô nhập không điều khiển, Space một lần nhảy một lần, Esc thoát.
11	//   Trang B `?test`: không có `stroll-people` trong cảnh.
12	//
13	//   npm run build && npm run test:stroll
14	//
15	//   Oracle mục 3 (không dùng bản đồ va chạm): tam giác thế giới của các lưới rắn, xếp vào lưới ô 2 m để chỉ thử tam giác gần nhân vật
16	//   (Raycaster trên cả cảnh với 24 000 tia không xong trong thời gian hợp lý trên SwiftShader). Thử tia bằng Ray.intersectTriangle
17	//   không loại mặt sau = vật liệu DoubleSide. Lưới dùng: nhà level gần của THREE.LOD (InstancedMesh, mọi instance còn hiện quanh khung đi dạo),
18	//   `dragon-body` (thân rồng), `dragon-head` (cả nhóm đầu rồng), `sh-tower` (tháp Cầu sông Hàn), `rf-landmarks` (địa danh ven sông, gồm cả
19	//   cầu tàu, lan can, hàng khóa và tượng cá chép Cầu Tình Yêu). Không dùng: cây, cột đèn, ghế, xe, người, dây văng, bảng quảng cáo (spec §4: đi xuyên được).
20	//   Cao độ tia tính từ cao độ đứng tại chỗ (không từ chân khi đang nhảy): spec chỉ chặn trong tầm người tính từ mặt đứng.
21	import { fileURLToPath } from 'node:url';
22	import { serveDir, launch, openApp, frames } from './lib.mjs';
23	
24	const problems = [];
25	const check = (name, ok) => { if (!ok) problems.push(name); console.log(`${ok ? 'đạt ' : 'LỖI '} ${name}`); return ok; };
26	
27	/* Chạy trong trang: hàm dùng chung (đặt nhân vật, tìm vùng, tia thẳng xuống) */
28	function installHelpers() {
29	  const a = window.__app, S = a.stroll, T = a.THREE;
30	  const map = () => S.stroll.map;
31	  const zoneAt = (x, z) => {
32	    for (const zn of map().zones) {
33	      if (x < zn.x0 || x > zn.x1 || z < zn.z0 || z > zn.z1) continue;
34	      if (zn.gate !== undefined && map().closed.has(zn.gate)) continue;
35	      return zn;
36	    }
37	    return null;
38	  };
39	  const put = (x, z) => {
40	    const s = S.stroll.state, g = S.stGroundY(map(), x, z);
41	    s.x = x; s.z = z; s.y = g; s.vy = 0; s.air = false; s.evac = false; s.speed = 0; s.tx = x; s.tz = z; s.photo = 0;
42	    return g;
43	  };
44	  /* vật đi xuyên được (spec §4) hoặc không phải mặt rắn: bỏ qua khi tìm mặt đứng */
45	  const through = (o) => {
46	    if (o.isInstancedMesh || o.isPoints || o.isLine || o.isSprite || o.name === 'stroll-people') return true;
47	    for (let p = o; p; p = p.parent) if (!p.visible) return true;
48	    return false;
49	  };
50	  const rc = new T.Raycaster(); rc.layers.enableAll(); rc.camera = a.camera;
51	  const down = (x, y, z) => {
52	    rc.set(new T.Vector3(x, y + 3, z), new T.Vector3(0, -1, 0)); rc.near = 0; rc.far = 10;
53	    for (const h of rc.intersectObject(a.scene, true)) if (!through(h.object)) return { y: h.point.y, name: h.object.name || h.object.type, par: h.object.parent?.name || '' };
54	    return null;
55	  };
56	  window.__st = { zoneAt, put, down };
57	}
58	
59	const srv = await serveDir(fileURLToPath(new URL('../dist/', import.meta.url)));
60	const browser = await launch();
61	try {
62	  const A = await openApp(browser, srv.url + '?explore=stroll');
63	  const P = A.page;
64	  await frames(P, 3);
65	  const has = await P.evaluate(() => !!(window.__app && window.__app.stroll && window.__app.stroll.stroll));
66	  check('có __app.stroll', has);
67	  if (!has) throw new Error('chưa có chế độ đi dạo (__app.stroll)');
68	  await P.evaluate(installHelpers);
69	
70	  // Mục 1 — vào chế độ
71	  {
72	    const r = await P.evaluate(() => {
73	      const a = window.__app, S = a.stroll, s = S.stroll.state, C = S.CONFIG_stroll;
74	      const vis = (sel) => { a.ui?.reveal(document.querySelector(sel)); const e = document.querySelector(sel); return !!e && e.getClientRects().length > 0 && getComputedStyle(e).visibility !== 'hidden'; };
75	      const hidden = ['[data-bridge="dragon"]', '[data-view="tour"]', '[data-view="allTour"]', '#tourCaption', '.specs', 'h1'].filter((q) => vis(q));
76	      a.ui?.closeSheets();   // reveal mở tờ điều khiển; tờ còn mở thì Esc đầu chỉ đóng tờ (compactUI)
77	      const d = window.__st.down(s.x, s.y, s.z);
78	      return { mode: a.cam.mode, ctl: a.controls.enabled, ex: document.body.classList.contains('explore'), st: document.body.classList.contains('stroll'), act: S.stroll.active(),
79	        leaked: hidden, x: s.x, z: s.z, y: s.y, sx: C.spawn.x, sz: C.spawn.z, hit: d, obj: !!a.scene.getObjectByName('stroll-people') };
80	    });
81	    check(`1 cam.mode ${r.mode}, controls ${r.ctl}, body.explore ${r.ex}, body.stroll ${r.st}, active ${r.act}, scene có stroll-people ${r.obj}`, r.mode === 'stroll' && r.ctl === false && r.ex && r.st && r.act && r.obj);
82	    check(`1 bảng tham quan ẩn (lọt: ${r.leaked.join(',') || '-'})`, r.leaked.length === 0);
83	    check(`1 xuất phát slot −1 tại (${r.x.toFixed(2)}, ${r.z.toFixed(2)}) = spawn (${r.sx}, ${r.sz})`, Math.abs(r.x - r.sx) < 1e-6 && Math.abs(r.z - r.sz) < 1e-6);
84	    check(`1 y ${r.y.toFixed(3)} = mặt lề Cầu Rồng ${r.hit ? r.hit.y.toFixed(3) + ' (' + r.hit.name + ')' : '-'} ± 0,02`, !!r.hit && Math.abs(r.y - r.hit.y) <= 0.02);
85	  }
86	
87	  // Mục 2 — cao độ tại 12 điểm mẫu
88	  {
89	    const r = await P.evaluate(() => {
90	      const S = window.__app.stroll, SHZ = -1080;
91	      const pts = [
92	        ['Cầu Rồng lề Nam', -240, 17.4], ['Cầu Rồng lề Bắc', 150, -17.6], ['Cầu Rồng lòng đường gần đầu Tây', -300, 9], ['Cầu Rồng đường dẫn Đông (vỉa hè)', 345, 18.2],
93	        ['Cầu sông Hàn lề Nam phần cố định', -150, SHZ + 5.5], ['Cầu sông Hàn lề Bắc nhịp quay', 40, SHZ - 5.5], ['Cầu sông Hàn lòng đường', 200, SHZ + 3], ['Cầu sông Hàn đường dẫn Đông', 300, SHZ + 2.5],
94	        ['bờ Tây lối dạo', -275, -500], ['bờ Đông lối dạo', 275, -600], ['bờ Tây đường Bạch Đằng', -305, -300], ['Cầu Tình Yêu', 240, -78]
95	      ];
96	      return pts.map(([n, x, z]) => {
97	        const ok = S.stValid(S.stroll.map, x, z, 0), y = window.__st.put(x, z), d = window.__st.down(x, y, z);
98	        return { n, x, z, ok, y, hit: d };
99	      });
100	    });
101	    for (const p of r) check(`2 ${p.n} (${p.x}, ${p.z}): hợp lệ ${p.ok}, chân ${p.y.toFixed(3)}, mặt trúng ${p.hit ? p.hit.y.toFixed(3) + ' ' + p.hit.name + (p.hit.par ? '<' + p.hit.par : '') : '-'} (≤ 0,15)`,
102	      p.ok && !!p.hit && Math.abs(p.y - p.hit.y) <= 0.15);
103	  }
104	
105	  // Mục 3 + 4 — 20 000 bước ngẫu nhiên, oracle bằng tam giác thật của lưới rắn
106	  {
107	    const r = await P.evaluate(() => {
108	      const a = window.__app, S = a.stroll, T = a.THREE, C = S.CONFIG_stroll, map = S.stroll.map, B = C.bounds, R = C.radius;
109	      const Ray = new T.Raycaster().ray.constructor;
110	      /* --- gom tam giác thế giới của các lưới rắn vào lưới ô 2 m --- */
111	      const CELL = 2, cells = new Map(), tri = [];
112	      const key = (ix, iz) => ix * 100003 + iz;
113	      const v = [new T.Vector3(), new T.Vector3(), new T.Vector3()], mw = new T.Matrix4(), mi = new T.Matrix4(), p = new T.Vector3(), q = new T.Quaternion(), sc = new T.Vector3();
114	      const boxes = [];   // hộp bao thế giới của từng nhà (cho mục 5)
115	      const counts = {};
116	      const addGeo = (geo, m, tag, box) => {
117	        const pos = geo.attributes.position, idx = geo.index, n = idx ? idx.count : pos.count;
118	        for (let i = 0; i + 2 < n; i += 3) {
119	          for (let k = 0; k < 3; k++) v[k].fromBufferAttribute(pos, idx ? idx.getX(i + k) : i + k).applyMatrix4(m);
120	          const x0 = Math.min(v[0].x, v[1].x, v[2].x), x1 = Math.max(v[0].x, v[1].x, v[2].x), z0 = Math.min(v[0].z, v[1].z, v[2].z), z1 = Math.max(v[0].z, v[1].z, v[2].z);
121	          if (box) { box.x0 = Math.min(box.x0, x0); box.x1 = Math.max(box.x1, x1); box.z0 = Math.min(box.z0, z0); box.z1 = Math.max(box.z1, z1); }
122	          if (x1 < B.x0 - 5 || x0 > B.x1 + 5 || z1 < B.z0 - 5 || z0 > B.z1 + 5) continue;
123	          const t = tri.length; tri.push([v[0].clone(), v[1].clone(), v[2].clone(), tag]);
124	          for (let ix = Math.floor(x0 / CELL); ix <= Math.floor(x1 / CELL); ix++) for (let iz = Math.floor(z0 / CELL); iz <= Math.floor(z1 / CELL); iz++) {
125	            const k = key(ix, iz); let l = cells.get(k); if (!l) { l = []; cells.set(k, l); } l.push(t);
126	          }
127	          counts[tag] = (counts[tag] || 0) + 1;
128	        }
129	      };
130	      const addObj = (root, tag) => {
131	        root.updateMatrixWorld(true);
132	        root.traverse((o) => {
133	          if (!o.isMesh) return;
134	          if (o.isInstancedMesh) { for (let i = 0; i < o.count; i++) { o.getMatrixAt(i, mi); mi.decompose(p, q, sc); if (sc.x < 1e-6) continue; addGeo(o.geometry, mw.multiplyMatrices(o.matrixWorld, mi), tag); } }
135	          else addGeo(o.geometry, o.matrixWorld, tag);
136	        });
137	      };
138	      a.scene.updateMatrixWorld(true);
139	      /* nhà: InstancedMesh level gần của THREE.LOD (như collectBuildings) */
140	      a.scene.traverse((o) => {
141	        if (!o.isInstancedMesh || !o.parent || !o.parent.isLOD || o.parent.levels[0]?.object !== o) return;
142	        for (let i = 0; i < o.count; i++) {
143	          o.getMatrixAt(i, mi); mi.decompose(p, q, sc); if (sc.x < 1e-6) continue;
144	          mw.multiplyMatrices(o.matrixWorld, mi); p.set(0, 0, 0).applyMatrix4(mw);
145	          if (p.x < B.x0 - 60 || p.x > B.x1 + 60 || p.z < B.z0 - 60 || p.z > B.z1 + 60) continue;
146	          const box = { x0: Infinity, x1: -Infinity, z0: Infinity, z1: -Infinity }; addGeo(o.geometry, mw, 'nhà', box); boxes.push(box);
147	        }
148	      });
149	      const named = {};
150	      for (const n of ['dragon-body', 'dragon-head', 'sh-tower', 'rf-landmarks']) { const o = a.scene.getObjectByName(n); named[n] = !!o; if (o) addObj(o, n); }
151	      /* --- 24 tia ngang dài R quanh (x, z) ở 3 cao độ trên mặt đứng --- */
152	      const ray = new Ray(), tgt = new T.Vector3(), seen = new Set();
153	      const DIRS = Array.from({ length: 8 }, (_, i) => [Math.cos(i * Math.PI / 4), Math.sin(i * Math.PI / 4)]);
154	      const probe = (x, g, z) => {
155	        seen.clear(); const hits = [];
156	        for (let ix = Math.floor((x - R) / CELL); ix <= Math.floor((x + R) / CELL); ix++) for (let iz = Math.floor((z - R) / CELL); iz <= Math.floor((z + R) / CELL); iz++) {
157	          const l = cells.get(key(ix, iz)); if (l) for (const t of l) seen.add(t);
158	        }
159	        if (!seen.size) return hits;
160	        for (const dh of [0.3, 1.0, 1.7]) for (const [dx, dz] of DIRS) {
161	          ray.origin.set(x, g + dh, z); ray.direction.set(dx, 0, dz);
162	          for (const t of seen) {
163	            const h = tri[t], hp = ray.intersectTriangle(h[0], h[1], h[2], false, tgt);
164	            if (hp && hp.distanceTo(ray.origin) <= R) { hits.push({ tag: h[3], dh, d: +hp.distanceTo(ray.origin).toFixed(4) }); break; }
165	          }
166	        }
167	        return hits;
168	      };
169	      /* --- 10 điểm xuất phát, 2 000 bước mỗi điểm --- */
170	      let seed = 20261111;
171	      const rnd = () => { seed = (seed + 0x6D2B79F5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
172	      const starts = [[-240, 17.4], [0, -10], [-300, 60], [-320, -500], [-320, -1150], [-150, -1074.5], [30, -1083], [320, -1150], [240, -78], [340, -660]];
173	      const badStart = [], fails = [], out4 = [], inp = { mx: 0, mz: 0, run: false, jump: false, camYaw: 0 };
174	      const BRIDGE = new Set(['shSwing', 'songHanW', 'songHanE', 'dragon', 'love']);
175	      let samples = 0, steps = 0, minY = Infinity, zonesSeen = new Set();
176	      const s = S.stroll.state;
177	      for (const [sx, sz] of starts) {
178	        if (!S.stValid(map, sx, sz, 0)) { badStart.push(`${sx},${sz}`); continue; }
179	        window.__st.put(sx, sz);
180	        let left = 0;
181	        for (let i = 0; i < 2000; i++) {
182	          inp.jump = false;
183	          if (left-- <= 0) {
184	            left = 10 + Math.floor(rnd() * 50);
185	            inp.mx = rnd() < 0.3 ? 0 : rnd() * 2 - 1; inp.mz = rnd() < 0.2 ? 0 : rnd() * 2 - 1; inp.run = rnd() < 0.5; inp.jump = rnd() < 0.4; inp.camYaw = rnd() * Math.PI * 2;
186	          }
187	          const dt = rnd() < 0.05 ? 0.1 : 1 / 30;
188	          S.stroll.step(dt, inp); steps++;
189	          if (s.y < minY) minY = s.y;
190	          if (i % 20 === 19) {
191	            samples++;
192	            const g = S.stGroundY(map, s.x, s.z), zn = window.__st.zoneAt(s.x, s.z);
193	            if (zn) zonesSeen.add(zn.id);
194	            const hits = probe(s.x, g === g ? g : s.y, s.z);
195	            if (hits.length && fails.length < 12) fails.push({ x: +s.x.toFixed(3), z: +s.z.toFixed(3), g: +(g === g ? g : s.y).toFixed(3), air: s.air, hits: hits.slice(0, 3) });
196	            else if (hits.length) fails.push(null);
197	            if (!(Math.abs(s.x) >= 262 - R || (zn && BRIDGE.has(zn.id))) && out4.length < 12) out4.push({ x: +s.x.toFixed(3), z: +s.z.toFixed(3), zone: zn ? zn.id : null });
198	          }
199	        }
200	      }
201	      return { tris: tri.length, counts, named, buildings: boxes.length, badStart, nFail: fails.length, fails: fails.filter(Boolean), samples, steps, out4, minY, landY: 2.5, zones: [...zonesSeen].sort() };
202	    });
203	    console.log(`   oracle: ${r.tris} tam giác (${JSON.stringify(r.counts)}), ${r.buildings} nhà; vùng đã đi qua: ${r.zones.join(',')}`);
204	    check(`3 có đủ lưới oracle ${JSON.stringify(r.named)}`, Object.values(r.named).every(Boolean) && r.buildings > 50);
205	    check(`3 10 điểm xuất phát hợp lệ (lỗi: ${r.badStart.join(' ') || '-'})`, r.badStart.length === 0);
206	    check(`3 ${r.steps} bước, ${r.samples} mẫu × 24 tia vào lưới rắn: ${r.nFail} mẫu trúng (= 0) ${r.nFail ? JSON.stringify(r.fails) : ''}`, r.nFail === 0 && r.steps === 20000);
207	    check(`4 mọi mẫu có |x| ≥ 261,65 hoặc trên cầu / Cầu Tình Yêu (lọt: ${r.out4.length ? JSON.stringify(r.out4) : '-'})`, r.out4.length === 0);
208	    check(`4 y thấp nhất ${r.minY.toFixed(3)} ≥ landY − 0,01`, r.minY >= 2.5 - 0.01);
209	  }
210	
211	  // Mục 5 — camera sát tường nhà
212	  {
213	    const r = await P.evaluate(() => {
214	      const a = window.__app, S = a.stroll, T = a.THREE, C = S.CONFIG_stroll, map = S.stroll.map, B = C.bounds, R = C.radius;
215	      const mi = new T.Matrix4(), mw = new T.Matrix4(), p = new T.Vector3(), q = new T.Quaternion(), sc = new T.Vector3();
216	      const boxes = [];
217	      a.scene.traverse((o) => {
218	        if (!o.isInstancedMesh || !o.parent || !o.parent.isLOD || o.parent.levels[0]?.object !== o) return;
219	        for (let i = 0; i < o.count; i++) {
220	          o.getMatrixAt(i, mi); mi.decompose(p, q, sc); if (sc.x < 1e-6) continue;
221	          mw.multiplyMatrices(o.matrixWorld, mi); p.set(0, 0, 0).applyMatrix4(mw);
222	          if (p.x < B.x0 - 30 || p.x > B.x1 + 30 || p.z < B.z0 - 30 || p.z > B.z1 + 30) continue;
223	          boxes.push({ x0: p.x - sc.x / 2, x1: p.x + sc.x / 2, z0: p.z - sc.z / 2, z1: p.z + sc.z / 2 });
224	        }
225	      });
226	      const inside = (x, z) => boxes.some((b) => x > b.x0 + 1e-6 && x < b.x1 - 1e-6 && z > b.z0 + 1e-6 && z < b.z1 - 1e-6);
227	      const cases = [];
228	      const P5 = [C.cam.pitchMin, C.cam.pitch, C.cam.pitchMax];
229	      for (const b of boxes) {
230	        if (cases.length >= 30) break;
231	        const mx = (b.x0 + b.x1) / 2, mz = (b.z0 + b.z1) / 2, e = R + 0.02;
232	        for (const [px, pz, nx, nz] of [[b.x1 + e, mz, 1, 0], [b.x0 - e, mz, -1, 0], [mx, b.z1 + e, 0, 1], [mx, b.z0 - e, 0, -1], [b.x1 + e, b.z0 + 2, 1, 0], [b.x0 - e, b.z1 - 2, -1, 0]]) {
233	          if (!S.stValid(map, px, pz, 0)) continue;
234	          cases.push([px, pz, Math.atan2(-nz, nx)]); break;   // mặt hướng ra ngoài tường: camera sau lưng nằm phía trong nhà nếu không tránh
235	        }
236	      }
237	      const bad = [], tgt = new T.Vector3(), cs = { yaw: 0, pitch: 0 };
238	      let minD = Infinity;
239	      cases.forEach(([x, z, yaw], i) => {
240	        const y = window.__st.put(x, z); S.stroll.state.yaw = yaw;
241	        cs.yaw = yaw; cs.pitch = P5[i % 3];
242	        S.stCamPlace(a.camera, tgt, S.stroll.state, cs, map, 0, true);
243	        const c = a.camera.position, d = Math.hypot(c.x - x, c.y - (y + C.cam.height), c.z - z);
244	        if (d < minD) minD = d;
245	        if (inside(c.x, c.z) || c.y < 2.5 || d < C.cam.minDist - 1e-6) bad.push({ x: +x.toFixed(2), z: +z.toFixed(2), cam: [+c.x.toFixed(2), +c.y.toFixed(2), +c.z.toFixed(2)], d: +d.toFixed(2) });
246	      });
247	      S.stCamPlace(a.camera, a.controls.target, S.stroll.state, S.stroll.cam, map, 0, true);
248	      return { n: cases.length, bad, minD };
249	    });
250	    check(`5 ${r.n} vị trí sát tường nhà: camera ngoài chân đế nhà, y ≥ 2,5, cách đầu ≥ minDist (nhỏ nhất ${r.minD.toFixed(2)} m) (lỗi: ${r.bad.length ? JSON.stringify(r.bad.slice(0, 5)) : '-'})`, r.n === 30 && r.bad.length === 0);
251	  }
252	
253	  // Mục 8 — draw call của người đi dạo
254	  {
255	    const r = await P.evaluate(() => {
256	      const a = window.__app, S = a.stroll, { renderer, scene, camera } = a, mesh = S.avatars.mesh;
257	      window.__st.put(-240, 17.4); S.stroll.state.yaw = 0; S.stroll.cam.yaw = 0; S.stroll.cam.pitch = S.CONFIG_stroll.cam.pitch;
258	      S.stroll.step(1 / 60, { mx: 0, mz: 0, run: false, jump: false, camYaw: 0 });
259	      S.stCamPlace(camera, a.controls.target, S.stroll.state, S.stroll.cam, S.stroll.map, 0, true);
260	      const calls = () => { renderer.render(scene, camera); renderer.info.reset(); renderer.render(scene, camera); return renderer.info.render.calls; };
261	      const on = calls(); mesh.visible = false; const off = calls(); mesh.visible = true;
262	      return { on, off, layer: mesh.layers.mask, cast: mesh.castShadow };
263	    });
264	    check(`8 đi dạo: ${r.on} lệnh vẽ, ẩn người đi dạo ${r.off}: chênh ${r.on - r.off} (= 1); lớp ${r.layer}, bóng ${r.cast}`, r.on - r.off === 1 && r.layer === 2 && r.cast === false);
265	  }
266	
267	  // Mục 7 — cầu quay
268	  {
269	    const SHX = await P.evaluate(() => {
270	      window.__st.put(5, -1077);
271	      window.__frames = 0; const tick = () => { window.__frames++; requestAnimationFrame(tick); }; tick();
272	      window.__app.songHan.ctrl.start(60);
273	      return window.__app.songHan.ctrl.cfg.fixedStart;
274	    });
275	    const r1 = await P.evaluate((X) => new Promise((ok) => {
276	      const a = window.__app, s = a.stroll.stroll.state, f0 = window.__frames;
277	      const w = () => {
278	        const f = window.__frames - f0;
279	        if (Math.abs(s.x) >= X && !s.evac) return ok({ f, x: s.x, z: s.z, state: a.songHan.ctrl.state, mode: a.cam.mode });
280	        if (f > 600) return ok({ f, x: s.x, z: s.z, state: a.songHan.ctrl.state, mode: a.cam.mode, timeout: true });
281	        requestAnimationFrame(w);
282	      };
283	      w();
284	    }), SHX);
285	    check(`7 cầu quay: sau ${r1.f} khung nhân vật ở x = ${r1.x.toFixed(2)} (|x| ≥ ${SHX}), trạng thái ${r1.state} ≠ CLOSED, camera vẫn ${r1.mode}`, !r1.timeout && Math.abs(r1.x) >= SHX && r1.state !== 'CLOSED' && r1.mode === 'stroll');
286	    const walkIn = () => P.evaluate((X) => {
287	      const S = window.__app.stroll, s = S.stroll.state; let minAx = Infinity;
288	      const inp = { mx: 0, mz: 1, run: false, jump: false, camYaw: s.x > 0 ? Math.PI : 0 };   // đi thẳng về tim cầu
289	      for (let i = 0; i < 500; i++) { S.stroll.step(1 / 30, inp); minAx = Math.min(minAx, Math.abs(s.x)); }
290	      return { minAx, state: window.__app.songHan.ctrl.state };
291	    }, SHX);
292	    const r2 = await walkIn();
293	    check(`7 khi chưa đóng (${r2.state}): 500 bước về tim cầu, |x| nhỏ nhất ${r2.minAx.toFixed(3)} ≥ ${SHX}`, r2.state !== 'CLOSED' && r2.minAx >= SHX);
294	    await P.evaluate(() => { const c = window.__app.songHan.ctrl; c.speed = 3000; window.__keepClosing = setInterval(() => c.requestClose(), 100); });
295	    await P.waitForFunction(() => window.__app.songHan.ctrl.state === 'CLOSED', null, { timeout: 240000 });
296	    await P.evaluate(() => clearInterval(window.__keepClosing));
297	    await frames(P, 2);
298	    const r3 = await walkIn();
299	    check(`7 cầu đóng lại: vào lại được nhịp quay (|x| nhỏ nhất ${r3.minAx.toFixed(2)})`, r3.state === 'CLOSED' && r3.minAx < SHX - 5);
300	  }
301	
302	  // Mục 6 — phím
303	  {
304	    await P.evaluate(() => { const S = window.__app.stroll; window.__st.put(-240, 17.4); S.stroll.state.yaw = 0; S.stroll.cam.yaw = Math.PI; window.__app.keys.clear(); });
305	    await P.focus('canvas');
306	    const p0 = await P.evaluate(() => { const s = window.__app.stroll.stroll.state; return { x: s.x, z: s.z }; });
307	    await P.keyboard.down('w');
308	    await frames(P, 60);
309	    const p1 = await P.evaluate(() => { const s = window.__app.stroll.stroll.state; return { x: s.x, z: s.z, speed: s.speed }; });
310	    const dx = p1.x - p0.x, dz = p1.z - p0.z, d = Math.hypot(dx, dz);
311	    check(`6 giữ W 60 khung, camera nhìn về −X: dịch (${dx.toFixed(2)}, ${dz.toFixed(2)}) theo hướng camera`, d > 1 && -dx / d > 0.99);
312	    await P.evaluate(() => window.dispatchEvent(new Event('blur')));
313	    await frames(P, 60);
314	    const p2 = await P.evaluate(() => { const s = window.__app.stroll.stroll.state; return { speed: s.speed, keys: window.__app.keys.size, x: s.x }; });
315	    await frames(P, 5);
316	    const x3 = await P.evaluate(() => window.__app.stroll.stroll.state.x);
317	    check(`6 blur khi đang giữ W: keys ${p2.keys} (= 0), sau 60 khung tốc độ ${p2.speed} (= 0), đứng yên (${(x3 - p2.x).toExponential(1)})`, p2.keys === 0 && p2.speed === 0 && x3 === p2.x);
318	    await P.keyboard.up('w');
319	    // gõ trong ô nhập: không điều khiển nhân vật (Review Focus 3)
320	    await P.evaluate(() => { const i = document.createElement('input'); i.id = '__stTestInput'; i.style.cssText = 'position:fixed;left:0;top:0;z-index:99'; document.body.appendChild(i); });
321	    await P.focus('#__stTestInput');
322	    const q0 = await P.evaluate(() => window.__app.stroll.stroll.state.x);
323	    await P.keyboard.type('wwwd wasd');
324	    await frames(P, 20);
325	    const q1 = await P.evaluate(() => ({ x: window.__app.stroll.stroll.state.x, keys: window.__app.keys.size, v: document.getElementById('__stTestInput').value, air: window.__app.stroll.stroll.state.air }));
326	    check(`6 gõ "${q1.v}" trong ô nhập: nhân vật đứng yên (${(q1.x - q0).toExponential(1)}), keys ${q1.keys}`, q1.v === 'wwwd wasd' && q1.x === q0 && q1.keys === 0 && !q1.air);
327	    await P.evaluate(() => document.getElementById('__stTestInput').remove());
328	    await P.focus('canvas');
329	    // giữ Space: nhảy đúng một lần
330	    await P.evaluate(() => { window.__jumps = 0; let prev = false; const s = window.__app.stroll.stroll.state; const w = () => { if (s.air && !prev) window.__jumps++; prev = s.air; window.__jw = requestAnimationFrame(w); }; w(); });
331	    await P.keyboard.down(' ');
332	    await frames(P, 80);
333	    await P.keyboard.up(' ');
334	    await frames(P, 30);
335	    const jumps = await P.evaluate(() => { cancelAnimationFrame(window.__jw); return window.__jumps; });
336	    check(`6 giữ Space 80 khung: nhảy ${jumps} lần (= 1)`, jumps === 1);
337	    // Esc thoát
338	    await P.evaluate(() => { window.__reloadMark = 1; });
339	    await P.keyboard.press('Escape');
340	    await P.waitForFunction(() => !window.__reloadMark, null, { timeout: 240000 });
341	    await P.waitForURL((u) => !u.href.includes('explore='), { timeout: 240000, waitUntil: 'commit' });
342	    check('6 Esc thoát: tải lại thật, URL không còn explore=', !P.url().includes('explore='));
343	  }
344	  check('console sạch (trang đi dạo)', A.errors.length === 0);
345	  if (A.errors.length) console.log(A.errors.join('\n'));
346	  await P.close();
347	
348	  // Mục 8b — trang ?test không explore: không có người đi dạo trong cảnh
349	  {
350	    const N = await openApp(browser, srv.url);
351	    await frames(N.page, 3);
352	    const r = await N.page.evaluate(() => ({ obj: !!window.__app.scene.getObjectByName('stroll-people'), mode: window.__app.cam.mode, st: document.body.classList.contains('stroll'), act: window.__app.stroll?.stroll.active() }));
353	    check(`8 ?test không explore: không có stroll-people (${r.obj}), mode ${r.mode}, body.stroll ${r.st}, active ${r.act}`, !r.obj && r.mode === 'orbit' && !r.st && r.act === false);
354	    check('console sạch (trang ?test)', N.errors.length === 0);
355	    await N.page.close();
356	  }
357	} catch (e) {
358	  problems.push('ngoại lệ: ' + e); console.log(e);
359	} finally {
360	  await browser.close(); srv.close();
361	}
362	console.log(problems.length ? `stroll-check: LỖI (${problems.length}): ${problems.join('; ')}` : 'stroll-check: đạt');
363	process.exit(problems.length ? 1 : 0);
